  ypot_der_avg_quad = (ypotL_quad + ypotR_quad)/2.0; 
  ypot_der_jump_quad = (ypotR_quad - ypotL_quad)/2.0; 
  ypot_der_surf_n[3] = ypot_der_avg_quad + gsign(alpha_quad)*ypot_der_jump_quad; 

