343	// Chooses the boundary (lower- or upper-edge) kernel for direction 'dir',
344	// discriminating between periodic, nonperiodic (physical BC), and
345	// multiblock (SKIP) treatment of the non-owning side's data.
346	GKYL_CU_D
347	static gk_collisionless_flux_surf_t
348	choose_gk_collisionless_flux_boundary_conf_kern(int dir, int cdim, int vdim, int poly_order,
349	  enum gkyl_gyrokinetic_bc_type bc, enum gkyl_edge_loc edge)
350	{
351	  bool is_lower = edge == GKYL_LOWER_EDGE;
352	  if (bc == GKYL_BC_GK_SKIP) {
353	    if (dir == 0)
354	      return (is_lower? ser_gk_collisionless_flux_boundary_surfx_lower_multib_kernels
355	                       : ser_gk_collisionless_flux_boundary_surfx_upper_multib_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
356	    else if (dir == 1)
357	      return (is_lower? ser_gk_collisionless_flux_boundary_surfy_lower_multib_kernels
358	                       : ser_gk_collisionless_flux_boundary_surfy_upper_multib_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
359	    else if (dir == 2)
360	      return (is_lower? ser_gk_collisionless_flux_boundary_surfz_lower_multib_kernels
361	                       : ser_gk_collisionless_flux_boundary_surfz_upper_multib_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
362	    else
363	      return NULL;
364	  }
365	  else if (bc == GKYL_BC_GK_SPECIES_PERIODIC || bc == GKYL_BC_GK_FIELD_PERIODIC) {
366	    if (dir == 0)
367	      return (is_lower? ser_gk_collisionless_flux_boundary_surfx_lower_periodic_kernels
368	                       : ser_gk_collisionless_flux_boundary_surfx_upper_periodic_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
369	    else if (dir == 1)
370	      return (is_lower? ser_gk_collisionless_flux_boundary_surfy_lower_periodic_kernels
371	                       : ser_gk_collisionless_flux_boundary_surfy_upper_periodic_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
372	    else if (dir == 2)
373	      return (is_lower? ser_gk_collisionless_flux_boundary_surfz_lower_periodic_kernels
374	                       : ser_gk_collisionless_flux_boundary_surfz_upper_periodic_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
375	    else
376	      return NULL;
377	  }
378	  else {
379	    if (dir == 0)
380	      return (is_lower? ser_gk_collisionless_flux_boundary_surfx_lower_nonperiodic_kernels
381	                       : ser_gk_collisionless_flux_boundary_surfx_upper_nonperiodic_kernels)[cv_index[cdim].vdim[vdim]].kernels[poly_order];
382	    else if (dir == 1)
